from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def _parse_step_name(name: str):
    """Parse a step name, returning (step_factory, arg_or_None).

    A bare name like "upper" has no argument.  A colon-separated name
    like "truncate:3" carries the part after the colon as a string
    argument.
    """
    if ":" in name:
        prefix, _, arg = name.partition(":")
        return STEPS.get(prefix), arg
    return STEPS.get(name), None


def lookup(name: str):
    factory, arg = _parse_step_name(name)
    if factory is None:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    if factory is Truncate:
        if arg is None or arg == "":
            raise ValueError(f"truncate requires a length, got {name!r}")
        try:
            length = int(arg)
        except ValueError:
            raise ValueError(
                f"truncate length must be an integer, got {arg!r}"
            )
        return Truncate(length)
    return factory()

